package org.apache.commons.lang3;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;
import java.util.Locale;
import org.apache.commons.lang3.text.WordUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for StringUtils.containsNone(CharSequence, char[])
 */
public class StringUtils_containsNone_TriageGen1Test {



















    @Test
    public void testContainsNone_UnicodeBMP() {
        // Test with characters in the Basic Multilingual Plane
        // 'Ω' is U+03A9
        assertTrue(StringUtils.containsNone("abc", new char[]{'Ω'}));
        assertFalse(StringUtils.containsNone("Ωbc", new char[]{'Ω'}));
    }
}
